<?php if ( ! defined( 'ABSPATH' ) ) { exit; } ?><div id="sd-mobile-drawer" class="sd-mobile-drawer" hidden><div class="sd-mobile-overlay" data-sd-close-menu></div><aside class="sd-mobile-panel" aria-label="<?php esc_attr_e( 'Mobile navigation', 'social-discovery' ); ?>"><button class="sd-mobile-close" type="button" data-sd-close-menu aria-label="<?php esc_attr_e( 'Close menu', 'social-discovery' ); ?>">×</button><?php sd_render_site_branding(); ?><nav class="sd-mobile-nav"><?php sd_menu( has_nav_menu( 'mobile' ) ? 'mobile' : 'primary' ); ?></nav><?php if ( is_user_logged_in() ) : ?><div class="sd-mobile-member-links"><a href="<?php echo esc_url( sd_auth_profile_url() ); ?>"><?php esc_html_e( 'My profile', 'social-discovery' ); ?></a><a href="<?php echo esc_url( sd_auth_account_url() ); ?>"><?php esc_html_e( 'Account settings', 'social-discovery' ); ?></a><a href="<?php echo esc_url( sd_auth_logout_url() ); ?>"><?php esc_html_e( 'Log out', 'social-discovery' ); ?></a></div><?php elseif ( sd_get_option( 'sd_header_auth' ) ) : ?><div class="sd-mobile-auth"><a href="<?php echo esc_url( sd_auth_url( 'login', wp_login_url() ) ); ?>"><?php esc_html_e( 'Log in', 'social-discovery' ); ?></a><?php if ( get_option( 'users_can_register' ) ) : ?><a class="sd-button sd-button-primary" href="<?php echo esc_url( sd_auth_url( 'register', wp_registration_url() ) ); ?>"><?php esc_html_e( 'Join free', 'social-discovery' ); ?></a><?php endif; ?></div><?php endif; ?></aside></div>
